import {imageSrc} from './core.mjs';
import {workspaceEntries} from './workspace-list.mjs';
import {sealStatusText} from './integrity-view.mjs';
export function workspaceListPage(data,filters,h,checks){
 const {t,esc,n,note,title,tag,link,btn,when}=h,result=workspaceEntries(data.drafts,{...filters,checks,lang:filters.lang});
 const statuses=[['current',t('当前方案','Current')],['draft',t('可编辑草稿','Drafts')],['sealed',t('本地定稿','Local seals')],['review',t('待复核定稿','Seal review')],['archived',t('已归档','Archived')]];
 const phases=type=>[t('项目资料','Project details'),t('发行规则','Launch terms'),type==='nft'?t('NFT 内容','NFT content'):t('保护与分账','Protection & splits'),t('核对定稿','Review & seal')];
 const workings={...data.workings};if(data.working?.raw&&!workings[data.working.raw.type])workings[data.working.raw.type]=data.working;
 const forms=Object.entries(workings).filter(([type,w])=>['nft','token'].includes(type)&&w?.raw&&(w.edited!==false||w.id));
 const statusLabel=entry=>entry.state==='archived'?t('已归档','Archived'):entry.record.sealed?sealStatusText(entry.check?.status??'checking',t):entry.progress.readyForLocalReview?t('资料齐备 · 待核对','Data complete · Review next'):t('资料待补全','Data incomplete');
 const editLabel=progress=>progress.readyForLocalReview?t('核对并定稿','Review & seal'):progress.nextStep===1&&progress.needsFutureStart?t('更新开始时间','Update start time'):t('继续完善','Continue editing');
 const card=entry=>{
  const {record:d,state,progress}=entry,cover=imageSrc(d.raw.cover,{demo:true}),date=d.updatedAt??d.createdAt;
  const primary=state==='archived'?btn('workspace-restore',t('恢复到当前方案','Restore to current'),'secondary',`data-id="${esc(d.id)}"`):d.sealed
   ?link('#/project/'+encodeURIComponent(d.id),state==='sealed'?t('打开参与页','Open participant view'):t('查看定稿复核','Review local seal'),'button secondary')
   :btn('edit',editLabel(progress),'secondary',`data-id="${esc(d.id)}" data-step="${progress.nextStep}"`);
  return `<article class="workspace-card"><a class="workspace-card-art" href="#/manage/${encodeURIComponent(d.id)}" aria-label="${esc(d.raw.name||t('未命名草稿','Untitled draft'))}">${cover?`<img data-fallback src="${esc(cover)}" alt="">`:`<span>${esc((d.raw.name||'E').slice(0,1))}</span>`}</a><div class="workspace-card-body"><div class="between"><span class="eyebrow">${d.raw.type==='nft'?'NFT':t('代币','TOKEN')} · $${esc(d.raw.symbol||'—')}</span>${tag(statusLabel(entry))}</div><h3>${link('#/manage/'+encodeURIComponent(d.id),esc(d.raw.name||t('未命名草稿','Untitled draft')))}</h3>${d.preservedFromWorking?`<p class="preserved-label">${t('切换前保留的编辑进度','Editing progress preserved before switching')}</p>`:''}${progress?`<p class="workspace-progress">${t('资料检查','Data checks')} ${progress.completeSections} / ${progress.totalSections} · ${progress.readyForLocalReview?t('仍需核对并确认','Review and acknowledgement still required'):phases(d.raw.type)[progress.nextStep]}</p>`:`<p class="workspace-progress">${t('仅本地版本 · 未公开上线','Local version only · Not publicly launched')}</p>`}<small>${Number.isFinite(Date.parse(date))?when(date):t('更新时间未记录','Update time not recorded')}</small><div class="actions">${primary}${link('#/manage/'+encodeURIComponent(d.id),t('管理 →','Manage →'),'text-link')}${state!=='archived'?btn('workspace-archive',t('归档','Archive'),'text-link',`data-id="${esc(d.id)}"`):''}</div></div></article>`;
 };
 return `${title('CREATOR WORKSPACE',t('每一个方案，<br>都有清楚的下一步。','Every plan.<br>A clear next step.'),t('在这里继续编辑、核对定稿和整理本地方案。定稿仍是本地版本，不会自动发布。','Continue editing, review seals and organize local plans. Sealing stays local and never publishes automatically.'))}<div class="actions workspace-actions">${btn('workspace-new',t('新建 NFT 方案','New NFT plan'),'primary','data-type="nft"')}${btn('workspace-new',t('新建代币方案','New token plan'),'secondary','data-type="token"')}${link('#/verify',t('校验方案 JSON','Check manifest JSON'),'button secondary')}${link('#/costs/example-orbit',t('运营测算','Operating plan'),'text-link')}</div>
 ${forms.length?`<section class="working-forms"><div class="section-heading"><h2>${t('继续上次编辑','Continue where you left off')}</h2></div><div class="working-grid">${forms.map(([type,w])=>`<article class="working-card"><div><span class="eyebrow">${type==='nft'?'NFT':'TOKEN'} · ${t('浏览器自动保存','BROWSER AUTO-SAVE')}</span><h3>${esc(w.raw.name||t('未命名方案','Untitled plan'))}</h3><p>${t('第','Step')} ${Math.min(4,(Number(w.step)||0)+1)} / 4 · ${phases(type)[Math.max(0,Math.min(3,Number(w.step)||0))]}</p></div><div class="actions">${btn('workspace-resume',t('继续编辑','Resume editing'),'secondary',`data-type="${type}"`)}${btn('workspace-keep',t('另存进度','Save progress separately'),'text-link',`data-type="${type}"`)}${btn('workspace-close',t('收起编辑','Close editor'),'text-link',`data-type="${type}"`)}</div></article>`).join('')}</div></section>`:''}
 <section class="workspace-library" aria-label="${t('本地方案库','Local plan library')}"><div class="section-heading"><h2>${t('本地方案库','Local plan library')}</h2><p>${n(result.total)} ${t('份方案 · 不代表真实发行','plans · Not live launches')}</p></div><div class="workspace-tabs" role="group" aria-label="${t('方案状态','Plan status')}">${statuses.map(([value,label])=>btn('workspace-status',`${label} <span>${n(result.counts[value])}</span>`,filters.status===value?'selected':'',`data-value="${value}" aria-pressed="${filters.status===value}"`)).join('')}</div><div class="workspace-controls"><label class="field"><span class="sr-only">${t('搜索本地方案','Search local plans')}</span><input id="workspace-search" type="search" value="${esc(filters.search)}" placeholder="${t('搜索名称、代号或简介','Search name, symbol or description')}" maxlength="200"></label><label class="field">${t('类型','Type')}<select id="workspace-type">${[['all',t('全部类型','All types')],['nft','NFT'],['token',t('代币','Token')]].map(([v,label])=>`<option value="${v}" ${filters.type===v?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">${t('排序','Sort')}<select id="workspace-sort">${[['updated',t('最近更新','Recently updated')],['name',t('项目名称','Project name')],['start',t('开始时间','Start time')]].map(([v,label])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${label}</option>`).join('')}</select></label></div>${filters.status==='archived'?note(t('归档只调整列表。原方案、定稿指纹、演示记录和直接访问都保留；恢复不会修改发行规则。','Archiving only organizes the list. Plans, seals, demo records and direct access remain available. Restoring does not change launch rules.')):note(t('资料齐备和本地定稿都不等于真实发行就绪。合约、身份、Gas、内容持久化及审计仍需独立接入与核验。','Complete data and a local seal are not live-launch readiness. Contracts, identity, Gas, content persistence and audits still need independent integration and verification.'))}<p class="workspace-result-count" role="status">${t('显示','Showing')} ${n(result.entries.length)} ${t('份方案','plans')}</p><div class="workspace-grid">${result.entries.length?result.entries.map(card).join(''):`<div class="empty"><span>◇</span><h3>${t('这里没有匹配的方案','No matching plans here')}</h3><p>${t('可以调整搜索与筛选，或新建一份 NFT / 代币方案。归档方案可随时恢复。','Adjust search/filters or create an NFT/token plan. Archived plans can be restored at any time.')}</p>${btn('workspace-clear',t('重置筛选','Reset filters'),'secondary')}</div>`}</div></section>
 <details class="panel workspace-backup"><summary>${t('导入、备份与旧版草稿','Import, backup & legacy drafts')}</summary><p>${t('浏览器数据只保存在本机。备份包含全部方案、归档和演示记录；恢复只合并，不覆盖已有内容。','Browser data stays on this device. Backups include all plans, archive organization and demo records. Recovery merges without overwriting existing content.')}</p><div class="actions"><label class="button secondary file-button">${t('导入方案 JSON','Import plan JSON')}<input id="import-file" type="file" accept="application/json,.json"></label><label class="button secondary file-button">${t('恢复备份 / 分包','Restore backup / parts')}<input id="restore-file" type="file" multiple accept="application/json,.json"></label>${btn('backup',t('备份全部本地数据','Back up local data'),'secondary')}${btn('backup-split',t('生成分包备份','Create backup parts'),'secondary')}</div><p class="muted">${t('旧版数据不会自动执行或覆盖。需要按当前规则重新核对。','Legacy data is never executed or overwritten automatically. Review it under current rules.')}</p></details>`;
}
